// builds the MP3 encoder: src/wasm/mp3enc.c (+ mp3_tables.h) → src/compose/mp3_wasm.js (the module as base64, embedded in the
// bundle: no extra file to fetch, works inside a Worker). Needs clang with the wasm32 target. The generated file is kept in src/,
// so a normal build does not need clang. Usage: node tools/mp3_build.cjs
const { execFileSync } = require('child_process'), fs = require('fs'), path = require('path');
const ROOT = path.join(__dirname, '..'), C = path.join(ROOT, 'src', 'wasm', 'mp3enc.c'), OUT = path.join(ROOT, 'src', 'compose', 'mp3_wasm.js'), TMP = path.join(ROOT, 'build', 'mp3enc.wasm');
fs.mkdirSync(path.dirname(TMP), { recursive: true });
execFileSync('clang', ['--target=wasm32', '-O3', '-nostdlib', '-fno-builtin', '-mnontrapping-fptoint', '-mbulk-memory', '-Wall', '-Wno-unused-function', '-Wno-unused-but-set-variable',
  '-Wl,--no-entry', '-Wl,-z,stack-size=262144', '-Wl,--strip-all', '-Wl,--initial-memory=8388608', '-o', TMP, C], { stdio: 'inherit' });
const b = fs.readFileSync(TMP), src = fs.readFileSync(C, 'utf8') + fs.readFileSync(path.join(ROOT, 'src', 'wasm', 'mp3_tables.h'), 'utf8'), h = require('crypto').createHash('sha256').update(src).digest('hex').slice(0, 16);
fs.writeFileSync(OUT, `/* generated by tools/mp3_build.cjs from src/wasm/mp3enc.c (sha256 ${h}) — do not edit */\nconst MP3_WASM_B64 = '${b.toString('base64')}';\nconst MP3_WASM_SRC = '${h}';\n`);
console.log(`mp3enc.wasm ${b.length} bytes → ${path.relative(ROOT, OUT)}`);
